from pathlib import Path
import json,shutil,hashlib,os,importlib.util
from PIL import Image,ImageOps,ImageDraw,ImageFont
D=Path(__file__).resolve().parent;R=D.parents[2]
def write(p,t):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(t,encoding='utf-8')
def dump(p,v):write(p,json.dumps(v,ensure_ascii=False,indent=2)+'\n')
def rel(p,b):return os.path.relpath(p,b).replace('\\','/')
data=json.loads((D/'producao.json').read_text(encoding='utf-8'))
for up in json.loads((D/'correcoes.json').read_text(encoding='utf-8')):
 next(m for m in data['members'] if m['id']==up['id']).update(up)
dump(D/'producao.json',data)
notes={
'geordraco':'Dois braços e duas pernas; mão na lança e mão no escudo. Helmet com crânio curto e viseira fechada, face em relevo no escudo e no peito. Placas claras ficaram mais marfim aquecido que prata fria; leitura metalizada é gráfica, não render realista. Rabiola única separada da capa. Estrutura mais convencional de cavaleiro, preservada como contraste aos três experimentos anatômicos.',
'lacustrel':'Correção dirigida retirou a mão da lâmina. Uma mão segura a empunhadura e a outra está aberta; espada contínua com armação e tensão próprias. Faces prateadas nas ombreiras, visor fechado, duas pernas e uma rabiola. Ponta da espada próxima da borda direita, completa. Silhueta de duelista alta permanece uma das formas mais convencionais.',
'valdrisa':'V2 rompe o corpo humano: duas pernas digitígradas em garra, dois braços, duas velas gigantes e cauda anatômica em S. Correção removeu rabiola duplicada que cruzava o torso. Rabiola/terminal único ligado à ponta da cauda, com três bandeirolas; a almática permanece nessa peça. Helmet e relevo dracônico nas placas. Gesto é pouso/resgate proposto, não animação pronta. Margens estreitas em algumas pontas das velas, sem corte visível.',
'joanacendra':'Dois braços e duas pernas; mão na haste, outra sobre o peito; face prateada no peitoral e nas joelheiras. Correção encurtou o remate dourado para deixar margem superior. Rabiola distinta da capa e estandarte. Corpo robusto com visor fechado e cor magenta nas membranas.',
'cidraco':'Dois braços e duas pernas, sabre e broquel em mãos distintas. Ombreira assimétrica e grande, joelheiras em relevo, peito amplo quieto. Helmet fechado, olhos verdes, rabiola única distinta da capa. Diferença de proporções existe, mas a anatomia ainda é a do cavaleiro bípede convencional.',
'tomoeryu':'Dois braços e duas pernas, duas mãos agarram a mesma haste contínua; ponta e base completas. Dois arcos largos no helmet, viseira fechada, uma grande ombreira dracônica e joelho em relevo. Cinco painéis de saia e duas abas posteriores. Rabiola única. Silhueta de placas segmentadas, postura menos dinâmica que o giro imaginado no brief.',
'bradamara':'Duas pernas dracônicas e dois braços; mãos separadas na mesma haste de marreta, antebraços grandes e peito profundo. Duas velas de quadril funcionam como contrapeso; cauda anatômica termina em rabiola trançada única. Faces douradas em ombros e arma, helmet fechado. Corpo muito mais robusto e baixo que os primeiros cinco. Pose está em preparação de golpe, não sequência certificada.',
'rolandor':'Dois braços e nenhuma perna: torso sustentado por uma única cauda serpentina ancorada em S. Uma mão no montante, outra no olifante; instrumento separado da face. Duas grandes velas de capa enquadram os ombros com faces de dragão. Viseira fechada, terminal de rabiola ligado à cauda. É revisão anatômica autoral, não alegação sobre Roland histórico.'
}
unknowns='Novos nomes, lore e vínculos com facções são propostas. Não há ligação automática com os onze cavaleiros, Armada dos Lobos, Crystais Pipas ou famílias anteriores. Pré-evoluções, obtenção, níveis e integração não definidos.'
spec=importlib.util.spec_from_file_location('v',R/'.agents/skills/soulmonsters-charts/scripts/validar_chart.py');v=importlib.util.module_from_spec(spec);spec.loader.exec_module(v)
records=[];checks=[];cards=[]
for m in data['members']:
 p=R/'art/creatures'/m['id']/f'concept-v{m["version"]}';p.mkdir(parents=True,exist_ok=True)
 shutil.copy2(m['source'],p/'concept.png');write(p/'prompt.txt',m['prompt']+'\n')
 if m['correction']:
  write(p/'prompt-correcao.txt',m['correction']+'\n')
  if m['correction_previous']:shutil.copy2(m['correction_previous'],p/'antes-correcao.png')
 if m['previous']:
  old=R/'art/creatures'/m['id']/'concept-v1';old.mkdir(parents=True,exist_ok=True)
  shutil.copy2(m['previous']['source'],old/'concept.png');write(old/'prompt.txt',m['previous']['prompt']+'\n')
  write(old/'revisao.md','# Histórico — direção anterior\n\nBípede convencional anterior à crítica do autor sobre falta de ousadia. Substituído na apresentação atual por concept-v2. Não aprovado.\n')
  dump(old/'manifest.json',dict(id=m['id'],name=m['name'],decision_status='superseded',production_status='concept',source=m['previous']['source'],sha256=hashlib.sha256((old/'concept.png').read_bytes()).hexdigest(),superseded_by='../concept-v2/concept.png'))
 source=next(s for s in data['sources'] if s['id']==m['id'])
 write(p/'brief.md',f'# {m["name"]} — cavaleiro draconiano\n\n## Definido pelo autor\n\nCriar oito cavaleiros(as) draconianos com helmets próximos do princípio do Dukemon, placas com faces metalizadas de dragão e inspiração em cavaleiros/figuras guerreiras com lore. Reforço posterior: ousar em anatomia e silhueta, conforme duas imagens apresentadas.\n\n## Proposta individual\n\nInspiração: {m["inspiration"]} ({m["nature"]}). Adulto, estágio IV.\n\nArma: {m["weapon"]}. Verbo: {m["verb"]}.\n\n{m["lore"]}\n\n## Construção e ação solicitadas\n\n{m["prompt"]}\n\n## Conferido na arte\n\n{notes[m["id"]]}\n\n## Evidência versus invenção\n\n[{source["title"]}]({source["url"]}) · {source["entity"]}. {source["fact"]}\n\nAplicação: {source["application"]}\n\nNenhuma arte externa usada como input. O Tramadraco próprio forneceu somente acabamento e construção, sem vínculo evolutivo. {unknowns}\n')
 write(p/'revisao.md',f'# Conferência — {m["name"]}\n\n{notes[m["id"]]}\n\nInspecionado individualmente após geração e no conjunto. Design proposto, não aprovado automaticamente. Fundo branco; não há recortes, rig, animações, grade de pixel art ou integração certificados. Vistas ocultas e juntas sob movimento precisam de model sheet futuro.\n')
 with Image.open(p/'concept.png') as im:meta=dict(width=im.width,height=im.height,mode=im.mode,alpha_extrema=im.getextrema()[-1] if im.mode=='RGBA' else None)
 dump(p/'manifest.json',dict(id=m['id'],name=m['name'],stage=4,date='2026-11-07',decision_status='proposed',production_status='concept',implementation_status='not_integrated',tool='image_gen.imagegen integrado',source=m['source'],sha256=hashlib.sha256((p/'concept.png').read_bytes()).hexdigest(),reference=rel(Path(data['reference']),p),reference_role='Arte própria: acabamento e material, sem copiar identidade ou estabelecer evolução.',prompt='prompt.txt',correction='prompt-correcao.txt' if m['correction'] else None,**meta))
 c=R/'documentation/creatures'/f'{m["id"]}-chart-v1';c.mkdir(parents=True,exist_ok=True)
 chart=dict(family_id=m['id'],scope='Um concept adulto draconiano proposto; sem pré-evoluções ou ligação com famílias anteriores.',nodes=[dict(id=m['id'],name=m['name'],kind='stage',stage=4,identity=m['weapon']+' · '+m['inspiration'],story=m['lore'],decision_status='proposed',production_status='concept',art=rel(p/'concept.png',c),brief=rel(p/'brief.md',c))],edges=[])
 dump(c/'chart.json',chart);errors=v.validate(chart,c);assert not errors,errors;checks.append(dict(family=m['id'],nodes=1,edges=0,errors=errors))
 write(c/'CHART.md',f'# {m["name"]}\n\nAdulto proposto inspirado em {m["inspiration"]}. {m["lore"]}\n\n[Arte]({rel(p/"concept.png",c)}) · [Brief]({rel(p/"brief.md",c)}) · [Conjunto]({rel(D/"index.html",c)}).\n\n{unknowns}\n')
 record=dict(id=m['id'],name=m['name'],inspiration=m['inspiration'],nature=m['nature'],weapon=m['weapon'],lore=m['lore'],art=rel(p/'concept.png',D),brief=rel(p/'brief.md',D),review=rel(p/'revisao.md',D));records.append(record)
 cards.append(f'<article><a href="{record["art"]}"><img src="{record["art"]}" alt="{m["name"]}, inspiração {m["inspiration"]}"></a><h2>{m["name"]}</h2><h3>{m["inspiration"]} · {m["weapon"]}</h3><p>{m["lore"]}</p><p><a href="{record["brief"]}">Brief</a> · <a href="{record["review"]}">Conferência</a></p></article>')
font=lambda n:ImageFont.truetype('C:/Windows/Fonts/arial.ttf',n)
def board(selected,cols,cellw,cellh,title,filename):
 rows=(len(selected)+cols-1)//cols
 im=Image.new('RGB',(cols*cellw,rows*cellh+125),'#eee9df');dr=ImageDraw.Draw(im)
 dr.text((32,22),title,font=font(42),fill='#18313d')
 for k,r in enumerate(selected):
  x=k%cols*cellw+12;y=k//cols*cellh+115
  dr.rectangle((x,y,x+cellw-24,y+cellh-22),fill='white')
  with Image.open((D/r['art']).resolve()) as src:thumb=ImageOps.contain(src.convert('RGB'),(cellw-54,cellh-138),Image.Resampling.LANCZOS)
  im.paste(thumb,(x+(cellw-24-thumb.width)//2,y+8+(cellh-138-thumb.height)//2))
  dr.text((x+18,y+cellh-113),r['name'],font=font(31),fill='#18313d')
  dr.text((x+18,y+cellh-66),r['inspiration'],font=font(24),fill='#536671')
 im.save(D/filename)
board(records,4,800,1100,'CAVALEIROS DRACONIANOS · OITO VOTOS PROPOSTOS','oito-draconianos.png')
board([r for r in records if r['id'] in ['valdrisa','bradamara','rolandor']],3,1000,1130,'RUPTURAS DE SILHUETA · PROPOSTAS EM REVISÃO','direcao-ousada.png')
dump(D/'grupo.json',dict(title='Oito Votos da Escama (nome coletivo proposto)',members=records,decision_status='proposed'))
dump(D/'fontes.json',data['sources'])
write(D/'PESQUISA.md','# Cavaleiros draconianos — estudo aplicado\n\n## Método e limites\n\nDukemon foi consultado no perfil oficial e sua arte local do benchmark foi aberta individualmente. Referências humanas e lendárias foram consultadas em textos curatoriais, acadêmicos e edição literária. Não foi lido todo o Orlando Furioso ou uma coleção inteira de armaduras. Britannica retornou erro de acesso; não foi usada como evidência. Nenhuma arte externa foi anexada à geração.\n\n## Helmet e armadura\n\nLeitura visual do Dukemon: cabeça pequena diante da massa de armadura; crânio de criatura acima do rosto cavaleiresco; bordas de placas separam superfícies claras, articulações escuras e elementos de tecido. O princípio transportado é estratificação de crânio/viseira e hierarquia, não réplica do desenho. Nossos helmets usam dragões próprios, viseiras fechadas e faces em relevo distribuídas entre ombro, peito ou joelho. Metal é indicado por facetas e faixas duras de luz no 2D, não iluminação PBR.\n\n## Crítica do autor e revisão\n\n'+data['critique']+'\n\nA análise das imagens do autor encontrou grande contraste entre corpo estreito e asas enormes, espaços vazios dominantes, elementos que mudam o apoio e pose ativa. Aplicação original: Valdrisa v2 troca botas por pés dracônicos e usa cauda/velas de resgate; Bradamara altera a escala dos braços e o equilíbrio da marreta; Rolandor substitui pernas por uma cauda ancorada. As outras cinco continuam mais próximas do cavaleiro bípede convencional. Isso está documentado, sem chamar a série toda de radicalmente revisada.\n\n## Fontes\n\n'+'\n\n'.join(f'### [{s["title"]}]({s["url"]})\n\n{s["entity"]} · consulta {s["accessed"]}. {s["fact"]}\n\nAplicação proposta: {s["application"]}' for s in data['sources'])+'\n')
write(D/'LORE.md','# Oito Votos da Escama\n\nNome coletivo e lore propostos, não escritos na bíblia como cânone. Não são cópias de pessoas reencarnadas: são almáticas que encenam dilemas de histórias humanas, lendárias e literárias em corpos draconianos de pipa. A alma permanece na rabiola de cada criatura; faces esculpidas na armadura são placas, não cabeças com almas extras.\n\nO pacto proposto é **“A força responde por aquilo que deixa vivo atrás de si.”** Cada voto limita sua própria força: conter, conciliar, recolher, reunir, escoltar, desviar, libertar e avisar. Isso permite que discordem sem dividir o mundo em oito elementos genéricos.\n\n'+'\n\n'.join(f'## {m["name"]} — {m["verb"]}\n\nInspiração: {m["inspiration"]} · {m["nature"]}. Arma: {m["weapon"]}.\n\n{m["lore"]}' for m in data['members'])+'\n\n## Conflitos propostos\n\nGeordraco quer conter a ameaça enquanto Bradamara pode querer romper a prisão imediatamente. Lacustrel tenta conciliar juramentos que Joanacendra exige tornar públicos. Cidraco prefere a retirada segura; Tomoeryu sustenta o desvio. Valdrisa insiste em voltar por um caído e Rolandor precisa decidir quando soar o alerta. São sementes narrativas, não eventos de campanha implementados.\n\n'+unknowns+'\n')
css='*{box-sizing:border-box}body{margin:0;background:#142834;color:#eee9df;font:18px/1.6 system-ui}main{max-width:1600px;margin:auto;padding:36px 24px}h1{font-size:clamp(35px,6vw,68px);line-height:1.1}a{color:#8bd8ce}a:focus-visible{outline:3px solid gold;outline-offset:5px}.board{width:100%;height:auto}.cards{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:40px}article{background:#eee9df;color:#18313d;padding:24px;border-radius:12px}article a{color:#126678}article img{width:100%;height:530px;object-fit:contain;background:white}@media(max-width:750px){.cards{grid-template-columns:1fr}article img{height:auto}}'
write(D/'index.html','<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cavaleiros draconianos · Soulmonsters</title><style>'+css+'</style><main><h1>Cavaleiros draconianos</h1><p>Oito adultos propostos: quatro cavaleiros e quatro cavaleiras. Helmet com crânio dracônico sobre viseira fechada, faces metalizadas em placas e construção de pipa viva. Figuras históricas, tradição semihistórica, mito e literatura são distinguidos na pesquisa.</p><p><a href="LORE.md">Lore e conflitos</a> · <a href="PESQUISA.md">Pesquisa e direção</a> · <a href="REVISAO.md">Conferência</a> · <a href="oito-draconianos.png">Prancha dos oito</a></p><h2>Resposta à crítica de ousadia</h2><p>Valdrisa v2, Bradamara e Rolandor exploram novas anatomias e grandes contrastes de volume. As cinco formas mais convencionais ficam como comparação, não como revisões radicais.</p><a href="direcao-ousada.png"><img class="board" src="direcao-ousada.png" alt="Valdrisa com cauda e velas gigantes, Bradamara robusta com marreta e Rolandor serpentino"></a><div class="cards">'+''.join(cards)+'</div><p>Concepts com fundo branco; sem grade técnica de pixel art, rig, animação ou integração. Nomes e lore propostos.</p></main></html>')
write(D/'REVISAO.md','# Conferência visual e técnica\n\n'+ '\n\n'.join(f'## {m["name"]}\n\n{notes[m["id"]]}' for m in data['members'])+'\n\n## Validação\n\nOito PNGs atuais abertos individualmente, correções localizadas de mão na espada, margem superior e rabiola duplicada. Oito charts de nó único conferidos pelo helper, hashes e dimensões registrados. Pranchas normalizam tamanho de apresentação, não escala canônica. Galeria responsiva com links e foco; checagem de arquivos não equivale a teste visual em navegador. Nenhum concept foi integrado ao jogo.\n')
dump(D/'validacao.json',dict(charts=checks,concepts=8,structural_ok=True,visual_scope='Inspeção individual e pranchas; não certifica rig, movimento, material físico ou anatomia oculta.'))
print('8 concepts atuais, 8 charts válidos, fontes, lore e duas pranchas registrados.')
